import React from 'react'
import { connect } from 'react-redux'
// import PropTypes from 'prop-types'
import { Row, Col, Button, Spin, notification } from 'antd'
import { get, size } from 'lodash'
import actions from '../../../../../../redux/productConfig/actions'
import FieldItem from './fieldItem'
import { FormPageStyleWrapper } from './index.style'
import { localStorageCheck } from '../../../../util/localstorageCheck'
import { payloadFormation, uniqueData } from './dataFormation'
import { finalEditPayloadMapper } from '../EditAttributes/tableDataformation'
const {
  getAllProductAttributes,
  addProductAttributesAction,
  resetProductConfigRedux
} = actions
class FormPage extends React.Component {
  state = {
    typeOfCreation: '',
    templateData: [],
    attributeData: [{
      id: 0,
      attribute_id: '',
      parent_attribute_id: null,
      parent_product_attribute_id: null,
      type: '',
      showTable: false,
      tableData: [],
      className: 'normal',
      is_array: false,
      showAddButton: false,
      deleteButton: false,
      disableSelectField: false
    }],
    step1Data: {},
    loading: false,
    step2Data: [],
    buttonDisabled: false
  }

  UNSAFE_componentWillReceiveProps (nextProps) {
    const {
      templateData,
      templateDatamessage,
      addProductAttributes
    } = nextProps
    if (templateDatamessage === 'success') {
      this.setState({
        templateData: get(templateData, 'data.details', [])
      })
      this.props.resetProductConfigRedux(['templateDatamessage'])
    }
    if (addProductAttributes === 'success') {
      notification['success']({
        message: 'Success',
        description: 'Product attributes created successfully'
      })
      this.props.resetProductConfigRedux(['addProductAttributes'])
      this.props.history.goBack()
    }
    if (addProductAttributes !== 'success' && addProductAttributes !== undefined) {
      notification['error']({
        message: 'Error',
        description: get(addProductAttributes, 'errors[0].description', '')
      })
      this.setState({
        loading: false
      })
      this.props.resetProductConfigRedux(['addProductAttributes'])
    }
  }

  componentDidMount () {
    const { location } = this.props
    // This value coming from policy creation button handler
    const formName = get(location, 'state.formName', '')
    switch (formName) {
      case 'step2': {
        const formData = get(location, 'state.formData.type', '')
        const initialData = get(location, 'state.formData.initialData')
        this.setState({
          typeOfCreation: formData,
          step2Data: initialData
        })
        this.props.getAllProductAttributes()
      }
        break
      case 'detail-page-attributes': {
        const formData = get(location, 'state.formData.type', '')
        this.setState({
          typeOfCreation: formData,
          step1Data: get(location, 'state.formData.step1Data', {}),
          step2Data: get(location, 'state.formData.step2Data', [])
        })
        this.props.getAllProductAttributes()
      }
        break
      default: {
        this.props.history.goBack()
      }
    }
  }

  updateDataHandler = (data) => {
    this.setState({
      attributeData: data
    })
    data.forEach(item => {
      const className = get(item, 'className')
      const itemType = get(item, 'type')
      const tableData = get(item, 'tableData', [])
      if (className === 'child' && itemType === 'object' && tableData.length === 0) {
        this.setState({
          buttonDisabled: true
        })
      } else {
        this.setState({
          buttonDisabled: false
        })
      }
    })
  }

  cancelAdd = () => {
    const { step1Data } = this.state
    if (size(step1Data) > 0) {
      this.props.history.goBack()
    } else {
      this.props.history.push({
        pathname: '/product-config/create-product/2/table',
        state: {
          formName: 'add-attributes-form'
        }
      })
    }
  }

  addAttributes =() => {
    const { typeOfCreation, step1Data, step2Data } = this.state
    const submittedData = localStorageCheck(window.sessionStorage.getItem('nestedAttributes')) || {}
    if (size(step1Data) > 0) {
      this.setState({
        loading: true
      })
      const productCode = get(step1Data, 'code', '')
      const payloadData = finalEditPayloadMapper(submittedData, typeOfCreation)
      const makeCallRequest = uniqueData(payloadData, step2Data)
      if (makeCallRequest.length === 0) {
        this.props.history.goBack()
      } else {
        this.props.addProductAttributesAction({ query: { productCode: productCode },
          body: {
            payload: makeCallRequest,
            type: 'add'
          }
        })
      }
    } else {
      let tableData = payloadFormation(submittedData, typeOfCreation)
      if (typeOfCreation === 'creation') {
        window.sessionStorage.setItem('policyCreation', JSON.stringify(tableData))
      } else {
        window.sessionStorage.setItem('endorsementCreation', JSON.stringify(tableData))
      }
      this.props.history.push({
        pathname: '/product-config/create-product/2/table',
        state: {
          formName: typeOfCreation === 'creation' ? 'policyCreation' : 'endorsementCreation'
        }
      })
    }
  }

  componentWillUnmount () {
    window.sessionStorage.removeItem('nestedAttributes')
  }

  render () {
    const { templateData, buttonDisabled, attributeData, step2Data } = this.state

    return (
      <FormPageStyleWrapper>
        <Row type='flex' justify='center'>
          <Col span={24}>
            <p className='heading-form'><b>Add Policy Creation Data Form</b></p>
          </Col>
        </Row>
        <Row type='flex' justify='center' align='middle'>
          <Col span={24}>
            <Spin spinning={templateData.length === 0} tip='Loading...'>
              {
                attributeData.map((item, index) => {
                  return (
                    <FieldItem
                      index={item.id}
                      key={item.id}
                      item={item}
                      parentData={attributeData}
                      templateData={templateData}
                      step2Data={step2Data}
                      updateData={this.updateDataHandler}
                    />
                  )
                })
              }
            </Spin>
          </Col>
        </Row>
        <Row type='flex' justify='center' gutter={50}>
          <Col>
            <Button onClick={this.cancelAdd}>Cancel</Button>
          </Col>
          <Col>
            <Button disabled={buttonDisabled} type='primary' onClick={this.addAttributes}>Submit</Button>
          </Col>
        </Row>
      </FormPageStyleWrapper>
    )
  }
}

export default connect(
  state => ({
    addProductAttributes: state.ProductConfigurable.addProductAttributesMessage,
    templateData: state.ProductConfigurable.getAllProductAttributes,
    templateDatamessage: state.ProductConfigurable.getAllProductAttributesMessage
  }), {
    getAllProductAttributes,
    resetProductConfigRedux,
    addProductAttributesAction
  }
)(FormPage)
